var cats = new[]{BuiltInCategory.OST_Casework, BuiltInCategory.OST_GenericModel, BuiltInCategory.OST_Furniture, BuiltInCategory.OST_PlumbingFixtures, BuiltInCategory.OST_SpecialityEquipment, BuiltInCategory.OST_Ceilings, BuiltInCategory.OST_Floors, BuiltInCategory.OST_Windows};
var outl = new List<object>();
foreach (var bc in cats) foreach (var e in new FilteredElementCollector(doc).OfCategory(bc).WhereElementIsNotElementType()) {
  var bb = e.get_BoundingBox(null);
  outl.Add(new { cat = e.Category.Name, id = e.Id.IntegerValue, name = e.Name, fam = (e as FamilyInstance)?.Symbol?.FamilyName,
   min = bb==null?null:new[]{Math.Round(bb.Min.X*0.3048,2),Math.Round(bb.Min.Y*0.3048,2),Math.Round(bb.Min.Z*0.3048,2)},
   max = bb==null?null:new[]{Math.Round(bb.Max.X*0.3048,2),Math.Round(bb.Max.Y*0.3048,2),Math.Round(bb.Max.Z*0.3048,2)} });
}
var walls = new List<object>();
foreach (Wall w in new FilteredElementCollector(doc).OfClass(typeof(Wall))) {
  var bb = w.get_BoundingBox(null);
  walls.Add(new { id = w.Id.IntegerValue, t = w.Name, h = Math.Round(w.get_Parameter(BuiltInParameter.WALL_USER_HEIGHT_PARAM).AsDouble()*0.3048,3), off = Math.Round(w.get_Parameter(BuiltInParameter.WALL_BASE_OFFSET).AsDouble()*0.3048,3), zmin=Math.Round(bb.Min.Z*0.3048,2), zmax=Math.Round(bb.Max.Z*0.3048,2), wd = Math.Round(w.Width*0.3048,3)});
}
return new { outl, walls };
